// Package kbspells holds the Turtle knowledge base's spell data: one oracle file per class under oracle/, generated by
// tools/kbrotgen from the recipes in tools/kbrotgen/recipes, and (item 3 of the KB work) the judge that scores a bot's
// casts against it.
//
// The oracle data is derived from the Turtle WoW knowledge base (stevemcqueenz),
// https://stevemcqueenz.github.io/turtle-knowledge-base-/#/, and the forum and Discord sources each rotation file lists;
// see NOTICE.
package kbspells

import (
	"embed"
	"io/fs"
)

//go:embed oracle/*.json
var oracleFiles embed.FS

// OracleFiles is the embedded oracle data, read-only: oracle/<class>.json for every class that has a KB rotation.
func OracleFiles() fs.FS { return oracleFiles }
